import React, { useState }  from 'react';
import { fetchWithAuth } from '../../utils/auth';
import 'Diario.css';
const RegistrarDiario = () => {
  const [fecha, setFecha] = useState('');
  const [horas, setHoras] = useState('');
  const [descripcion, setDescripcion] = useState('');

  const handleSubmit = async (e) => {
  e.preventDefault();


  try {
    const res = await fetchWithAuth('/diario/diario', {
      method: 'POST',
      body: JSON.stringify({
        fecha,
        horas: Number(horas),
        descripcion,
      }),
    });

    if (!res.ok) {
      const data = await res.json();
      throw new Error(data.message || data.error || 'No se pudo guardar la entrada');
    }

    alert('Registro guardado');
    setFecha('');
    setHoras('');
    setDescripcion('');
  } catch (err) {
    console.error(err);
    alert(`Error al guardar: ${err.message}`);
  }
};
return (
  <div className="flex min-h-screen flex-col bg-stone-50">

    <main className="mx-auto w-full max-w-5xl flex-1 px-4 py-10 sm:px-6 lg:px-8">
      <header className="mb-8">
        <p className="mb-2 text-sm font-semibold uppercase tracking-wider text-red-800">
          Diario de prácticas
        </p>
        <h1 className="text-3xl font-bold tracking-tight text-stone-900 sm:text-4xl">
          Registrar actividad
        </h1>
        <p className="mt-3 max-w-2xl text-stone-600">
          Anota la actividad realizada, el tiempo dedicado y una breve descripción.
        </p>
      </header>

      <section className="overflow-hidden rounded-2xl border border-stone-200 bg-white shadow-sm">
        <div className="border-b border-stone-200 bg-stone-100/70 px-6 py-5 sm:px-8">
          <h2 className="text-lg font-semibold text-stone-900">
            Nueva entrada
          </h2>
          <p className="mt-1 text-sm text-stone-600">
            Los campos marcados con * son obligatorios.
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6 px-6 py-6 sm:px-8 sm:py-8">
          <div className="grid gap-6 sm:grid-cols-2">
            <div>
              <label
                htmlFor="fecha"
                className="mb-2 block text-sm font-medium text-stone-800"
              >
                Fecha <span className="text-red-800">*</span>
              </label>
              <input
                id="fecha"
                type="date"
                value={fecha}
                onChange={(e) => setFecha(e.target.value)}
                required
                className="w-full rounded-lg border border-stone-300 bg-white px-3 py-2.5 text-stone-900 shadow-sm outline-none transition focus:border-red-800 focus:ring-2 focus:ring-red-800/20"
              />
            </div>

            <div>
              <label
                htmlFor="horas"
                className="mb-2 block text-sm font-medium text-stone-800"
              >
                Horas <span className="text-red-800">*</span>
              </label>
              <div className="relative">
                <input
                  id="horas"
                  type="number"
                  name="horas"
                  value={horas}
                  min={1}
                  max={8}
                  step={1}
                  onChange={(e) => setHoras(e.target.value)}
                  required
                  className="w-full rounded-lg border border-stone-300 bg-white px-3 py-2.5 pr-16 text-stone-900 shadow-sm outline-none transition focus:border-red-800 focus:ring-2 focus:ring-red-800/20"
                />
                <span className="pointer-events-none absolute inset-y-0 right-3 flex items-center text-sm text-stone-500">
                  horas
                </span>
              </div>
              <p className="mt-1.5 text-xs text-stone-500">
                Introduce un valor entre 1 y 8.
              </p>
            </div>
          </div>

          <div>
            <label
              htmlFor="descripcion"
              className="mb-2 block text-sm font-medium text-stone-800"
            >
              Descripción de la actividad <span className="text-red-800">*</span>
            </label>
            <textarea
              id="descripcion"
              value={descripcion}
              onChange={(e) => setDescripcion(e.target.value)}
              rows={5}
              required
              placeholder="Describe brevemente las tareas realizadas..."
              className="w-full resize-y rounded-lg border border-stone-300 bg-white px-3 py-2.5 text-stone-900 shadow-sm outline-none transition placeholder:text-stone-400 focus:border-red-800 focus:ring-2 focus:ring-red-800/20"
            />
          </div>

          <div className="flex flex-col-reverse gap-3 border-t border-stone-200 pt-6 sm:flex-row sm:justify-end">
            <button
              type="submit"
              className="inline-flex items-center justify-center rounded-lg bg-red-800 px-5 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-red-900 focus:outline-none focus:ring-2 focus:ring-red-800 focus:ring-offset-2"
            >
              Guardar actividad
            </button>
          </div>
        </form>
      </section>
    </main>

  </div>
);

